CREATE TABLE public.product_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_sku text NOT NULL, order_id uuid REFERENCES public.orders(id) ON DELETE SET NULL, customer_display_name text NOT NULL, city text NOT NULL DEFAULT '', rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), text text NOT NULL DEFAULT '', photo_urls jsonb NOT NULL DEFAULT '[]', source text NOT NULL CHECK(source IN ('order_link','facebook_comment','manual_import','demo')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','hidden','demo')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.product_reviews TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_reviews TO authenticated;
GRANT ALL ON public.product_reviews TO service_role;
ALTER TABLE public.product_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviews_public ON public.product_reviews FOR SELECT TO anon,authenticated USING(status='approved');
CREATE POLICY reviews_admin ON public.product_reviews FOR ALL TO authenticated USING(public.is_active_admin(auth.uid())) WITH CHECK(public.is_active_admin(auth.uid()));
CREATE INDEX reviews_sku_status ON public.product_reviews(product_sku,status);
CREATE UNIQUE INDEX review_order_once ON public.product_reviews(order_id) WHERE source='order_link';
CREATE TABLE public.product_review_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES public.orders(id) ON DELETE CASCADE, token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), product_sku text NOT NULL DEFAULT '002', consumed_at timestamptz, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.product_review_requests TO authenticated;
GRANT ALL ON public.product_review_requests TO service_role;
ALTER TABLE public.product_review_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY requests_admin ON public.product_review_requests FOR SELECT TO authenticated USING(public.is_active_admin(auth.uid()));
CREATE OR REPLACE FUNCTION public.camera_order_delivered(p_order uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM orders o WHERE o.id=p_order AND NOT o.is_return AND o.status NOT IN ('canceled','cancelled','merged') AND (o.status='delivered' OR EXISTS(SELECT 1 FROM courier_shipments s WHERE s.original_order_id=o.id AND NOT s.is_return AND (s.derived_state='DELIVERED' OR s.derived_status='DELIVERED_TO_CUSTOMER')))); $$;
REVOKE ALL ON FUNCTION public.camera_order_delivered(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.camera_order_delivered(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.camera_review_feed(p_preview boolean DEFAULT false) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(jsonb_agg(jsonb_build_object('id',r.id,'customer_display_name',r.customer_display_name,'city',r.city,'rating',r.rating,'text',r.text,'photo_urls',r.photo_urls,'source',r.source,'status',r.status,'created_at',r.created_at,'verified',r.source='order_link' AND r.order_id IS NOT NULL AND public.camera_order_delivered(r.order_id)) ORDER BY r.created_at DESC),'[]'::jsonb) FROM product_reviews r WHERE r.product_sku='002' AND (r.status='approved' OR (p_preview AND r.status='demo' AND r.source='demo')); $$;
REVOKE ALL ON FUNCTION public.camera_review_feed(boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.camera_review_feed(boolean) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.camera_landing_stats() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH camera_orders AS (SELECT DISTINCT o.id,o.created_at,o.city,o.status FROM orders o JOIN order_items i ON i.order_id=o.id WHERE i.sku='002' AND NOT o.is_return AND o.status NOT IN ('canceled','cancelled','merged')), sold AS (SELECT COALESCE(sum(i.quantity),0) AS n FROM order_items i JOIN orders o ON o.id=i.order_id WHERE i.sku='002' AND NOT o.is_return AND o.status NOT IN ('canceled','cancelled','merged')), recent AS (SELECT city FROM camera_orders WHERE created_at>now()-interval '2 hours' AND trim(city)<>'' ORDER BY created_at DESC LIMIT 12) SELECT jsonb_build_object('sold_units',(SELECT n FROM sold),'today_orders',(SELECT count(*) FROM camera_orders WHERE (created_at AT TIME ZONE 'Asia/Tbilisi')::date=(now() AT TIME ZONE 'Asia/Tbilisi')::date),'recent_cities',COALESCE((SELECT jsonb_agg(city) FROM recent),'[]'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.camera_landing_stats() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.camera_landing_stats() TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.camera_review_token_info(p_token uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('valid',EXISTS(SELECT 1 FROM product_review_requests r WHERE r.token=p_token AND r.consumed_at IS NULL AND public.camera_order_delivered(r.order_id))); $$;
REVOKE ALL ON FUNCTION public.camera_review_token_info(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.camera_review_token_info(uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.camera_submit_review(p_token uuid,p_rating integer,p_text text,p_photos jsonb DEFAULT '[]') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_request product_review_requests; v_order orders; v_id uuid; BEGIN SELECT * INTO v_request FROM product_review_requests WHERE token=p_token FOR UPDATE; IF v_request.id IS NULL OR v_request.consumed_at IS NOT NULL OR NOT public.camera_order_delivered(v_request.order_id) THEN RAISE EXCEPTION 'Review link is invalid or already used'; END IF; IF p_rating NOT BETWEEN 1 AND 5 OR length(trim(p_text)) NOT BETWEEN 3 AND 2000 OR jsonb_typeof(p_photos)<>'array' OR jsonb_array_length(p_photos)>3 THEN RAISE EXCEPTION 'Invalid review'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_photos) u WHERE u NOT LIKE 'https://%/storage/v1/object/public/review-photos/'||p_token::text||'/%') THEN RAISE EXCEPTION 'Invalid photo path'; END IF; SELECT * INTO v_order FROM orders WHERE id=v_request.order_id; INSERT INTO product_reviews(product_sku,order_id,customer_display_name,city,rating,text,photo_urls,source,status) VALUES('002',v_order.id,split_part(trim(v_order.customer_name),' ',1)||CASE WHEN split_part(trim(v_order.customer_name),' ',2)<>'' THEN ' '||left(split_part(trim(v_order.customer_name),' ',2),1)||'.' ELSE '' END,v_order.city,p_rating,trim(p_text),p_photos,'order_link','pending') RETURNING id INTO v_id; UPDATE product_review_requests SET consumed_at=now() WHERE id=v_request.id; RETURN v_id; END; $$;
REVOKE ALL ON FUNCTION public.camera_submit_review(uuid,integer,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.camera_submit_review(uuid,integer,text,jsonb) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.camera_review_sms_candidates() RETURNS TABLE(order_id uuid,order_number text,phone text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT o.id,o.public_order_number,o.customer_phone FROM orders o WHERE public.camera_order_delivered(o.id) AND EXISTS(SELECT 1 FROM order_items i WHERE i.order_id=o.id AND i.sku='002') AND NOT EXISTS(SELECT 1 FROM product_review_requests r WHERE r.order_id=o.id) AND NOT EXISTS(SELECT 1 FROM sms_logs l WHERE l.order_number=o.public_order_number AND l.type='review_request') ORDER BY o.created_at DESC; $$;
REVOKE ALL ON FUNCTION public.camera_review_sms_candidates() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.camera_review_sms_candidates() TO service_role;
CREATE OR REPLACE FUNCTION public.review_photo_upload_allowed(p_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM product_review_requests r WHERE r.token::text=split_part(p_path,'/',1) AND r.consumed_at IS NULL AND public.camera_order_delivered(r.order_id)) OR public.is_active_admin(auth.uid()); $$;
REVOKE ALL ON FUNCTION public.review_photo_upload_allowed(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.review_photo_upload_allowed(text) TO anon,authenticated;
CREATE POLICY review_photos_insert ON storage.objects FOR INSERT TO anon,authenticated WITH CHECK(bucket_id='review-photos' AND public.review_photo_upload_allowed(name));
CREATE POLICY review_photos_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='review-photos');